@RunWith(MockitoJUnitRunner.class)
public class ClosureReverseAbstractInterpreter_getPreciserScopeKnowingConditionOutcome_TriageGen1Test {

    private ClosureReverseAbstractInterpreter interpreter;
    private Map<String, Function<TypeRestriction, JSType>> restricters;
    private FlowScope blindScope;
    private FlowScope expectedNextScope;

    @Before
    public void setUp() {
        restricters = new HashMap<>();
        interpreter = spy(new ClosureReverseAbstractInterpreter(restricters));
        blindScope = mock(FlowScope.class);
        expectedNextScope = mock(FlowScope.class);
    }

    @Test
    public void testConditionNotCall() {
        Node condition = mock(Node.class);
        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.OTHER);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testConditionNotTwoChildren() {
        Node condition = mock(Node.class);
        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(3);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testCalleeNotGetProp() {
        Node condition = mock(Node.class);
        Node callee = mock(Node.class);
        Node param = mock(Node.class);

        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(com.google.javascript.jscomp.AST.NAME);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testParamNotQualifiedName() {
        Node condition = mock(Node.class);
        Node callee = mock(Node.class);
        Node param = mock(Node.class);

        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(com.google.javascript.jscomp.AST.GETPROP);
        when(param.isQualifiedName()).thenReturn(false);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testGetTypeIfRefinableReturnsNull() {
        Node condition = mock(Node.class);
        Node callee = mock(Node.class);
        Node param = mock(Node.class);

        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(com.google.javascript.jscomp.AST.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);

        // Mocking getTypeIfRefinable is tricky because it's likely a protected method in the same class.
        // We use spy to return null.
        doReturn(null).when(interpreter).getTypeIfRefinable(param, blindScope);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testLeftNotGoog() {
        Node condition = mock(Node.class);
        Node callee = mock(Node.class);
        Node param = mock(Node.class);
        Node left = mock(Node.class);
        Node right = mock(Node.class);
        JSType paramType = mock(JSType.class);

        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(com.google.javascript.jscomp.AST.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        doReturn(paramType).when(interpreter).getTypeIfRefinable(param, blindScope);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(com.google.javascript.jscomp.AST.NAME);
        when(left.getString()).thenReturn("notgoog");
        when(right.getType()).thenReturn(com.google.javascript.jscomp.AST.STRING);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
