        doReturn(paramType).when(interpreter).getTypeIfRefinable(param, blindScope);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(com.google.javascript.jscomp.AST.NAME);
        when(left.getString()).thenReturn("goog");
        when(right.getType()).thenReturn(com.google.javascript.jscomp.AST.NUMBER);

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

        assertSame(expectedNextScope, result);
    }

    @Test
    public void testRestricterNull() {
        Node condition = mock(Node.class);
        Node callee = mock(Node.class);
        Node param = mock(Node.class);
        Node left = mock(Node.class);
        Node right = mock(Node.class);
        JSType paramType = mock(JSType.class);

        when(condition.getType()).thenReturn(com.google.javascript.jscomp.AST.CALL);
        when(condition.getChildCount()).thenReturn(2);
        when(condition.getFirstChild()).thenReturn(callee);
        when(condition.getLastChild()).thenReturn(param);
        when(callee.getType()).thenReturn(com.google.javascript.jscomp.AST.GETPROP);
        when(param.isQualifiedName()).thenReturn(true);
        doReturn(paramType).when(interpreter).getTypeIfRefinable(param, blindScope);

        when(callee.getFirstChild()).thenReturn(left);
        when(callee.getLastChild()).thenReturn(right);
        when(left.getType()).thenReturn(com.google.javascript.jscomp.AST.NAME);
        when(left.getString()).thenReturn("goog");
        when(right.getType()).thenReturn(com.google.javascript.jscomp.AST.STRING);
        when(right.getString()).thenReturn("unknown_key");

        when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
            .thenReturn(expectedNextScope);

        FlowScope result = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

